        self.p=list(range(n)); self.rank=[0]*n
    def find(self,x):
        while self.p[x]!=x: x=self.p[x]
        return x
    def union(self,a,b):
        ra,rb=self.find(a),self.find(b)
        if ra==rb: return False
        if self.rank[ra]<self.rank[rb]: ra,rb=rb,ra
        self.p[rb]=ra; self.rank[ra]+=1
        return True
